pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Set up: deposit type(uint256).max wei to trigger overflow
        address user = address(0x1234);
        vm.deal(user, type(uint256).max);
        vm.prank(user);
        bool ok;
        try c.deposit{value: type(uint256).max}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: assert rejects overflow -> ok == false
        // Bug: require allows overflow -> ok == true
        assertTrue(ok == true);
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0xABCD);
        vm.deal(alice, 1);
        vm.prank(alice);
        try c.deposit{value: 1}() {
            // deposit succeeded in buggy version
        } catch {
            // deposit reverted in reference
            revert("Reference should not revert here");
        }
        // Now attempt to withdraw the 1 wei
        vm.prank(alice);
        try c.withdraw(1) {
            // In the reference, deposit reverted so balance unchanged — but actually the reference never reached this point
            // Since we only reach if deposit succeeded (buggy), this succeeds
        } catch {
            // withdraw fails in buggy because deposit 1 succeeded -> balance = 1, but then the buggy require allowed 0 wei deposit? No— the bug is assert vs require means overflow allowed
            // Actually the condition: in reference deposit(1) to zero balance passes assert (1>0) so succeeds. Wait the assert requires strict >, passes. The mutant requires >=, also passes. So both succeed.
            // The bug manifests when msg.value = 0: reference assert fails (0 > 0 false), mutant require passes (0 >= 0 true). So we deposit 0 wei.
        }

        // Reset: The key is deposit with 0 wei.
        vm.deal(alice, 0);
        vm.prank(alice);
        bool depositOk;
        try c.deposit{value: 0}() {
            depositOk = true;
        } catch {
            depositOk = false;
        }
        // Reference reverts (assert(0+0>0) fails), buggy accepts (require(0+0>=0) passes)
        // So depositOk should be false for reference but true for buggy.
        // But we cannot know which version we are on... We need to check post-state.
        // Since balance remains 0 if deposit reverted, but becomes 1 if deposit succeeded with 1 earlier? Actually we did two deposits.
        // Simpler: after the 0 deposit, check if balance increased.
        uint256 bal = c.balances(alice);
        // Reference: bal == 0 (since deposit reverts, no state change)
        // Buggy: bal == 1 (the earlier 1 deposit still there, or 0+0=0 balance unchanged). Actually 0 deposit doesn't change balance.
        // The only difference: in buggy, the deposit(0) succeeded but didn't change balance. So balance is same after.
        // We need a different approach.
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address alice = address(0x1234);
        vm.deal(alice, type(uint256).max);
        vm.prank(alice);
        // First deposit 1 wei to make sure msg.sender has a non-zero balance
        c.deposit{value: 1}();

        // Now deposit type(uint256).max - 1 wei, which will cause overflow when balance is 1
        uint256 overflowAmount = type(uint256).max - 1;
        vm.deal(alice, overflowAmount);
        vm.prank(alice);
        bool ok;
        try c.deposit{value: overflowAmount}() {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference: assert rejects overflow, so revert => ok == false
        // Bug: require allows, deposit succeeds => ok == true
        assertTrue(ok == false);
    }
}

