pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address user = address(0x123);
        vm.deal(user, 10 ether);
        vm.startPrank(user);
        c.deposit{value: 1}();
        c.deposit{value: 1}();
        vm.stopPrank();
        // Reference: balance = 2, bug: balance = 1
        bool ok;
        try c.withdraw(2) { ok = true; } catch { ok = false; }
        assertTrue(ok);
    }
}
